import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;

/**
 * Oct 3, 2016 | 12:28:10 PM
 * <pre>
 * <u>Rewritten Version</u>
 *
 * </pre>
 *
 * @author Essiennta Emmanuel (colourfulemmanuel@gmail.com)
 */
public class ProblemB {

    private void compute(char[] chars, PrintWriter output) {
        int position = 0;
        int maxSegment = 0;
        int pairs = 0;
        boolean inside = false;
        while (position < chars.length) {
            if (chars[position] == '(') {
                inside = true;
            } else if (chars[position] == ')') {
                inside = false;
            } else if (Character.isLetter(chars[position]))
                position--;
            if (inside) {
                while (++position != chars.length && chars[position] != ')' && !Character.isLetter(chars[position]));
                if (position == chars.length || !Character.isLetter(chars[position])) {
                    continue;
                }
                while (Character.isLetter(chars[++position]));
                pairs++;
            } else {
                while (++position != chars.length && chars[position] != '(' && !Character.isLetter(chars[position]));
                if (position == chars.length || !Character.isLetter(chars[position])) {
                    continue;
                }
                int startIdx = position;
                while (++position != chars.length && Character.isLetter(chars[position]));
                maxSegment = Math.max(maxSegment, position - startIdx);
            }
        }
        output.println(maxSegment + " " + pairs);
    }

    public static void main(String[] args) throws Exception {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {
            br.readLine();
            new ProblemB().compute(br.readLine().toCharArray(), pw);
        }
    }
}
